import { ButtonHTMLAttributes, useState } from 'react'

export const ACCORDION_VARIANT = {
  DEFAULT: 'default',
} as const
export type AccordionVariant = keyof typeof ACCORDION_VARIANT

export const accordionVariant: Record<AccordionVariant, string> = {
  DEFAULT: 'bg-black hover:bg-black-800 active:bg-grey-900',
}

export interface AccordionProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  options?: any
  selectedCatOptions?: any
  setSelectedCatOptions?: any
  variant?: AccordionVariant
}

export const Accordion = ({
  options,
  selectedCatOptions,
  setSelectedCatOptions,
  variant = 'DEFAULT',
}: AccordionProps) => {
  const [activePanel, setActivePanel] = useState<string | null>(null)

  const groupedItems: { [classId: string]: any[] } = {}
  const data = options
  const categorizeItem = (item: any) => {
    const splitted = item.classId.split('_')[0]
    const numericClassValue = parseInt(splitted.split('.')[0])
    if (numericClassValue < 200) {
      item.groupName = 'Patros'
    } else if (numericClassValue < 300) {
      item.groupName = 'Reius'
    } else if (numericClassValue < 500) {
      item.groupName = 'Caius'
    } else if (numericClassValue < 600) {
      item.groupName = 'Verkehrslenkungstafeln'
    } else if (numericClassValue < 721) {
      item.groupName = 'Ranta'
    } else {
      item.groupName = 'Lorem'
    }
    return item
  }

  const categorizedItems = data.map((item: any) => categorizeItem(item))
  // const categorizedItems = data.map((item: any) => categorizeItem(item));

  Object.values(categorizedItems).forEach((item: any) => {
    if (!groupedItems[item.groupName]) {
      groupedItems[item.groupName] = []
    }
    groupedItems[item.groupName].push(item)
  })

  const togglePanel = (classId: string) => {
    setActivePanel((prevActivePanel) => (prevActivePanel === classId ? null : classId))
  }

  const toggleItemSelection = (itemId: string) => {
    const index = selectedCatOptions.indexOf(itemId)
    if (index === -1) {
      setSelectedCatOptions([...selectedCatOptions, itemId])
    } else {
      const updatedselectedCatOptions = [...selectedCatOptions]
      updatedselectedCatOptions.splice(index, 1)
      setSelectedCatOptions(updatedselectedCatOptions)
    }
  }

  const [allSelected, setAllSelected] = useState(false)
  const toggleSelectAllItemsInGroup = (groupItems: any[]) => {
    const groupItemIds = groupItems.map((item) => item.id)
    if (groupItemIds.every((itemId) => selectedCatOptions.includes(itemId))) {
      const updatedSelectedCatOptions = selectedCatOptions.filter((itemId: string) => !groupItemIds.includes(itemId))
      setAllSelected(false)
      setSelectedCatOptions(updatedSelectedCatOptions)
    } else {
      setAllSelected(true)
      setSelectedCatOptions([...selectedCatOptions, ...groupItemIds])
    }
  }

  const isItemSelected = (itemId: string) => selectedCatOptions && selectedCatOptions.includes(itemId)

  const labels = ['Reius', 'Caius', 'Patros', 'Ranta', 'Lorem', 'Andere']

  return (
    <>
      <div className="w-full overflow-hidden border rounded border-brand-black">
        {Object.keys(groupedItems).map((classId: string) => {
          const items = groupedItems[classId]
          const isOpen = classId === activePanel
          return (
            <div
              key={classId}
              className={`relative ${isOpen ? 'h-[15em]' : 'h-[3.5em]'} accordion-item w-full flex-col py-4 
                        justify-start items-start overflow-hidden gap-2.5 border-b last:border-b-0 bg-brand-white 
                        hover:cursor-pointer focus:outline-none focus:border-blue-500 transition-all duration-700`}
            >
              <div className="bg-brand-white h-[2.5em] px-4 border-b" onClick={() => togglePanel(classId)}>
                {labels.find((label) => label === classId) || 'Andere'}
              </div>
              <div
                className="flex px-[1em] py-[0.3em] w-[10.5em] justify-between"
                onClick={() => {
                  toggleSelectAllItemsInGroup(items)
                }}
              >
                {allSelected ? (
                  <>
                    <p className="text-semibold">Alle entfernen</p>
                    <svg
                      width={24}
                      height={24}
                      viewBox="0 0 24 24"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                      className="relative flex-grow-0 flex-shrink-0 w-6 h-6"
                      preserveAspectRatio="none"
                    >
                      <g clipPath="url(#clip0_270_14209)">
                        <rect width={24} height={24} fill="white" />
                        <path d="M19 13H5V11H19V13Z" fill="black" />
                      </g>
                      <defs>
                        <clipPath id="clip0_270_14209">
                          <rect width={24} height={24} fill="white" />
                        </clipPath>
                      </defs>
                    </svg>
                  </>
                ) : (
                  <>
                    <p className="text-semibold">Alle auswählen</p>
                    <svg
                      width={24}
                      height={24}
                      viewBox="0 0 24 24"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                      className="relative flex-grow-0 flex-shrink-0 w-6 h-6"
                      preserveAspectRatio="none"
                    >
                      <g clipPath="url(#clip0_264_13558)">
                        <rect width={24} height={24} fill="white" />
                        <path d="M19 13H13V19H11V13H5V11H11V5H13V11H19V13Z" fill="black" />
                      </g>
                      <defs>
                        <clipPath id="clip0_264_13558">
                          <rect width={24} height={24} fill="white" />
                        </clipPath>
                      </defs>
                    </svg>
                  </>
                )}
              </div>
              <div className={`pb-[4em] bg-[#f0eff1] overflow-scroll ${isOpen ? 'h-[15em]' : 'h-[3.5em]'}`}>
                {items
                  .slice() // Create a shallow copy to avoid mutating the original array
                  .sort((a, b) => (a.name && b.name ? a.name.localeCompare(b.name) : 0)) // Sort items alphabetically by name
                  .map((item: any) => (
                    <div
                      className={`px-4 py-[0.5em] border-b border-[#d8e6f2] transition-all hover:bg-slate-200 ${
                        isItemSelected(item.id) ? 'bg-blue-100' : ''
                      }`}
                      key={item.id}
                      onClick={() => toggleItemSelection(item.id)}
                    >
                      {item.name}
                    </div>
                  ))}
              </div>
              <div className="absolute inset-y-0 right-0 flex items-start pt-[1em] top-0 px-2 text-gray-700 pointer-events-none">
                <div>
                  {isOpen ? (
                    <div className="transition-all rotate-0 duration-600">
                      <svg
                        viewBox="0 0 24 24"
                        fill="none"
                        xmlns="http://www.w3.org/2000/svg"
                        className="relative flex-grow-0 flex-shrink-0 w-6 h-6"
                        preserveAspectRatio="none"
                      >
                        <g clipPath="url(#clip0_626_593)">
                          <path d="M12 8L6 14L7.41 15.41L12 10.83L16.59 15.41L18 14L12 8Z" fill="black" />
                        </g>
                        <defs>
                          <clipPath id="clip0_626_593">
                            <rect width="24" height="24" fill="white" />
                          </clipPath>
                        </defs>
                      </svg>
                    </div>
                  ) : (
                    <div className="transition-all -rotate-180 duration-600">
                      <svg
                        viewBox="0 0 24 24"
                        fill="none"
                        xmlns="http://www.w3.org/2000/svg"
                        className="relative flex-grow-0 flex-shrink-0 w-6 h-6"
                        preserveAspectRatio="none"
                      >
                        <g clipPath="url(#clip0_626_593)">
                          <path d="M12 8L6 14L7.41 15.41L12 10.83L16.59 15.41L18 14L12 8Z" fill="black" />
                        </g>
                        <defs>
                          <clipPath id="clip0_626_593">
                            <rect width="24" height="24" fill="white" />
                          </clipPath>
                        </defs>
                      </svg>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )
        })}
      </div>
    </>
  )
}
